-- Centralized WhatsApp alarm gateway for Reception (online or post-sync).
-- Capability rows do NOT include patient names, phones, credentials or message content.
-- Every token is generated by the local backend, only its SHA-256 is persisted.
-- No cron: cleanup is bounded and only on future new Reception actions.
CREATE TABLE IF NOT EXISTS whatsapp_cloud.reception_alarm_requests(
 token_hash text PRIMARY KEY CHECK(token_hash~'^[0-9a-f]{64}$'),
 purpose text NOT NULL CHECK(purpose IN ('refresh','auth_check','manual')),
 source_type text NOT NULL DEFAULT '' CHECK(source_type IN ('','appointment','staged')),
 source_id integer,
 created_at timestamptz NOT NULL DEFAULT now(),
 expires_at timestamptz NOT NULL,
 acknowledged_at timestamptz,
 consumed_at timestamptz,
 CHECK(purpose <> 'manual' OR (source_type='appointment' AND source_id>0))
);
CREATE INDEX IF NOT EXISTS reception_alarm_requests_expiry_idx ON whatsapp_cloud.reception_alarm_requests(expires_at);
REVOKE ALL ON whatsapp_cloud.reception_alarm_requests FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE,DELETE ON whatsapp_cloud.reception_alarm_requests TO neondb_owner;
GRANT SELECT,INSERT,UPDATE,DELETE ON whatsapp_cloud.reception_alarm_requests TO neon_service;
-- Never print raw capability tokens. Only check existence and privileges.
SELECT COUNT(*)::int AS existing_requests FROM whatsapp_cloud.reception_alarm_requests;
